export class ParentsComponent {
  // =========================================================
  // Constructor
  // =========================================================
  constructor(parentService) {
    this.parentService = parentService;
    // =========================================================
    // Parents Data
    // =========================================================
    this.parents = [];
    // =========================================================
    // Filters
    // =========================================================
    this.searchText = '';
    this.selectedGender = 'All Gender';
    this.selectedStatus = 'All Status';
    // =========================================================
    // State
    // =========================================================
    this.loading = false;
    this.errorMessage = '';
    // =========================================================
    // Modals
    // =========================================================
    this.isModalOpen = false;
    this.isDetailsModalOpen = false;
    // =========================================================
    // Selected Parent
    // =========================================================
    this.selectedParent = null;
    // =========================================================
    // Add / Edit
    // =========================================================
    this.isEditMode = false;
    this.newParent = {
      name: '',
      email: '',
      phone: '',
      gender: '',
      status: 'Active'
    };
  }
  // =========================================================
  // Lifecycle
  // =========================================================
  ngOnInit() {
    this.loadParents();
  }
  // =========================================================
  // Load Parents
  // =========================================================
  loadParents() {
    this.loading = true;
    this.errorMessage = '';
    this.parentService.getAllParents().subscribe({
      next: response => {
        this.parents = response?.parents || [];
        this.loading = false;
      },
      error: error => {
        console.error('Error loading parents:', error);
        this.errorMessage = error?.error?.message || 'Failed to load parents';
        this.loading = false;
      }
    });
  }
  // =========================================================
  // Filtered Parents
  // =========================================================
  get filteredParents() {
    const search = this.searchText.toLowerCase().trim();
    return this.parents.filter(parent => {
      const user = parent.user || {};
      const name = (user.name || '').toLowerCase();
      const phone = (user.phone || '').toLowerCase();
      const email = (user.email || '').toLowerCase();
      // Search
      const matchesSearch = !search || name.includes(search) || phone.includes(search) || email.includes(search);
      // Gender
      const matchesGender = this.selectedGender === 'All Gender' || parent.gender === this.selectedGender.toLowerCase();
      // Status
      const matchesStatus = this.selectedStatus === 'All Status' || (this.selectedStatus === 'Active' ? user.isActive === true : user.isActive === false);
      return matchesSearch && matchesGender && matchesStatus;
    });
  }
  // =========================================================
  // Apply Filters
  // =========================================================
  applyFilters() {
    /*
     * Filtering is handled by
     * the filteredParents getter.
     *
     * This method is called from
     * the HTML when search/filter
     * values change.
     */
  }
  // =========================================================
  // Statistics
  // =========================================================
  get totalParents() {
    return this.parents.length;
  }
  get activeParents() {
    return this.parents.filter(parent => parent.user?.isActive === true).length;
  }
  get inactiveParents() {
    return this.parents.filter(parent => parent.user?.isActive === false).length;
  }
  get maleParents() {
    return this.parents.filter(parent => parent.gender === 'male').length;
  }
  // =========================================================
  // Parent Initials
  // =========================================================
  getParentInitials(name) {
    if (!name) {
      return '?';
    }
    return name.split(' ').filter(word => word.length > 0).map(word => word.charAt(0)).join('').substring(0, 2).toUpperCase();
  }
  // =========================================================
  // Add Parent
  // =========================================================
  onAddParentClick() {
    this.isEditMode = false;
    this.selectedParent = null;
    this.newParent = {
      name: '',
      email: '',
      phone: '',
      gender: '',
      status: 'Active'
    };
    this.isModalOpen = true;
  }
  // =========================================================
  // Edit Parent
  // =========================================================
  editParent(parent) {
    this.selectedParent = parent;
    this.isEditMode = true;
    this.newParent = {
      name: this.getParentName(parent) === 'Unknown' ? '' : this.getParentName(parent),
      email: this.getParentEmail(parent) === '-' ? '' : this.getParentEmail(parent),
      phone: this.getParentPhone(parent) === '-' ? '' : this.getParentPhone(parent),
      gender: parent.gender || '',
      status: parent.user?.isActive === true ? 'Active' : 'Inactive'
    };
    this.isModalOpen = true;
  }
  // =========================================================
  // Save Parent
  // =========================================================
  saveParent() {
    // Validation
    if (!this.newParent.name.trim() || !this.newParent.email.trim() || !this.newParent.gender) {
      alert('Please fill in the required fields.');
      return;
    }
    // =======================================================
    // Edit Existing Parent
    // =======================================================
    if (this.isEditMode && this.selectedParent) {
      const parent = this.selectedParent;
      // Update frontend data
      if (!parent.user) {
        parent.user = {};
      }
      parent.user.name = this.newParent.name.trim();
      parent.user.email = this.newParent.email.trim();
      parent.user.phone = this.newParent.phone.trim();
      parent.user.isActive = this.newParent.status === 'Active';
      parent.gender = this.newParent.gender;
    }
    // =======================================================
    // Add New Parent
    // =======================================================
    else {
      const newParent = {
        _id: 'local-' + Date.now(),
        user: {
          name: this.newParent.name.trim(),
          email: this.newParent.email.trim(),
          phone: this.newParent.phone.trim(),
          isActive: this.newParent.status === 'Active'
        },
        gender: this.newParent.gender
      };
      this.parents.push(newParent);
    }
    // Refresh filters
    this.applyFilters();
    // Close modal
    this.closeModal();
  }
  // =========================================================
  // Close Add/Edit Modal
  // =========================================================
  closeModal() {
    this.isModalOpen = false;
    this.isEditMode = false;
    this.selectedParent = null;
  }
  // =========================================================
  // View Parent
  // =========================================================
  viewParent(parent) {
    this.selectedParent = parent;
    this.isDetailsModalOpen = true;
  }
  // =========================================================
  // Close Details Modal
  // =========================================================
  closeDetailsModal() {
    this.isDetailsModalOpen = false;
    this.selectedParent = null;
  }
  // =========================================================
  // Delete Parent
  // =========================================================
  deleteParent(parent) {
    const parentId = parent._id;
